tasks_data = [(201, "Oddiy 'for' sikli va ro'yxat bo'yicha iteratsiya", "Uchta server nomi bo'yicha ketma-ket aylanib chiqing.", '#!/usr/bin/env bash\n\nfor server in "web-01" "db-01" "cache-01"; do\n    echo "Ulanish tekshirilmoqda: $server"\ndone\n', "'for var in item1 item2 ...; do ... done' ro'yxatdagi har bir elementni o'zlashtirib blok ichidagi buyruqlarni bajaradi.", 'Ulanish tekshirilmoqda: web-01\nUlanish tekshirilmoqda: db-01\nUlanish tekshirilmoqda: cache-01'), (202, "Brace expansion yordamida 'for' sikli: '{1..5}'", "1 dan 5 gacha bo'lgan sonlarni siklda chop eting.", '#!/usr/bin/env bash\n\nfor i in {1..5}; do\n    echo "Qadam: $i"\ndone\n', "'{start..end}' sintaksisi Bash tomonidan sikl boshlanishidan oldin ro'yxatga aylantiriladi.", 'Qadam: 1\nQadam: 2\nQadam: 3\nQadam: 4\nQadam: 5'), (203, "Qadamli brace expansion: '{0..20..5}'", '0 dan 20 gacha 5 qadam bilan sanab chiqing.', '#!/usr/bin/env bash\n\nfor val in {0..20..5}; do\n    echo "Qiymat: $val"\ndone\n', "'{start..end..step}' sintaksisida uchinchi raqam qadam (step) kattaligini bildiradi.", 'Qiymat: 0\nQiymat: 5\nQiymat: 10\nQiymat: 15\nQiymat: 20'), (204, "Harflar bo'yicha iteratsiya: '{A..E}'", "Alifbo harflari bo'ylab sikl aylantiring.", '#!/usr/bin/env bash\n\nfor ch in {A..E}; do\n    echo "Klaster zonasi: $ch"\ndone\n', "Brace expansion harflar (ASCII) oralig'ini ham to'liq qo'llab-quvvatlaydi.", 'Klaster zonasi: A\nKlaster zonasi: B\nKlaster zonasi: C\nKlaster zonasi: D\nKlaster zonasi: E'), (205, "Nol bilan to'ldirilgan raqamlar: '{01..05}'", 'Server nomlarining raqamlangan seriyasini generatsiya qiling.', '#!/usr/bin/env bash\n\nfor num in {01..04}; do\n    echo "node-$num.cluster.local"\ndone\n', "Brace expansion boshlang'ich formatdagi nollarni saqlab qoladi.", 'node-01.cluster.local\nnode-02.cluster.local\nnode-03.cluster.local\nnode-04.cluster.local'), (206, "C-uslubidagi 'for' sikli: 'for (( i=0; i<N; i++ ))'", 'Klassik 3 ta parametrli C sikli bilan hisoblagichni oshiring.', '#!/usr/bin/env bash\n\nfor (( i=1; i<=4; i++ )); do\n    echo "Iteratsiya #$i"\ndone\n', "'for (( init; condition; step ))' sintaksisi dinamik o'zgaruvchilar bilan ishlashda eng qulay va tezkor hisoblanadi.", 'Iteratsiya #1\nIteratsiya #2\nIteratsiya #3\nIteratsiya #4'), (207, 'C-style for siklida orqaga sanash', '10 dan 0 gacha 2 qadam bilan teskari sanab chiqing.', '#!/usr/bin/env bash\n\nfor (( count=6; count>=0; count-=2 )); do\n    echo "Ortga hisoblash: $count"\ndone\n', "Dekrement va arifmetik qisqartmalar C-style for siklida qulay qo'llaniladi.", 'Ortga hisoblash: 6\nOrtga hisoblash: 4\nOrtga hisoblash: 2\nOrtga hisoblash: 0'), (208, "Bir nechta o'zgaruvchili C-style for sikli", "Bitta siklda bir vaqtning o'zida ikkita o'zgaruvchini parallel boshqaring.", '#!/usr/bin/env bash\n\nfor (( i=1, j=10; i<=3; i++, j-=2 )); do\n    echo "i=$i, j=$j"\ndone\n', 'Vergul bilan ajratilgan ifodalar C-style siklida bir vaqtda bajariladi.', 'i=1, j=10\ni=2, j=8\ni=3, j=6'), (209, "Katalogdagi fayllar bo'yicha iteratsiya: 'for f in *.log'", "Papkadagi barcha log fayllarni aylanib chiqib ularning hajmini ko'rsating.", '#!/usr/bin/env bash\n\nmkdir -p /tmp/logs_test\ntouch /tmp/logs_test/app.log /tmp/logs_test/err.log\n\nfor f in /tmp/logs_test/*.log; do\n    echo "Fayl topildi: $(basename "$f")"\ndone\n', "Wildcard fayllar ro'yxatini hosil qiladi va sikl har bir fayl nomini qabul qiladi.", 'Fayl topildi: app.log\nFayl topildi: err.log'), (210, "Bo'sh moslik muammosi va 'nullglob' sozlamasi", 'Hech qanday fayl topilmaganda xato literal satr chiqishining oldini oling.', '#!/usr/bin/env bash\n\nshopt -s nullglob\ncount=0\n\nfor f in /tmp/mavjud_bolmagan_yo_l_123/*.xyz; do\n    ((count++))\ndone\n\necho "Topilgan fayllar soni: $count"\nshopt -u nullglob\n', "'shopt -s nullglob' agar wildcard hech qanday faylga mos kelmasa, uni literal matn sifatida qoldirmasdan bo'sh ro'yxatga aylantiradi.", 'Topilgan fayllar soni: 0'), (211, 'Skript argumentlari bo\'yicha \'for arg in "$@"\'', "Skriptga kiritilgan barcha argumentlarni bo'sh joylari bilan xavfsiz iteratsiya qiling.", '#!/usr/bin/env bash\n\nset -- "Alpha Node" "Beta Node"\n\nfor node in "$@"; do\n    echo "Tugun sozlanmoqda: [$node]"\ndone\n', '\'for arg in "$@"\' barcha pozitsion parametrlarni xavfsiz qabul qiladi.', 'Tugun sozlanmoqda: [Alpha Node]\nTugun sozlanmoqda: [Beta Node]'), (212, "Qisqartirilgan argumentlar sikli: 'for arg; do ... done'", 'Argumentlar ro\'yxatini \'in "$@"\' siz to\'g\'ridan-to\'g\'ri aylanib chiqing.', '#!/usr/bin/env bash\n\nset -- "file1.txt" "file2.txt"\n\nfor file; do\n    echo "Qayta ishlanmoqda: $file"\ndone\n', 'Agar \'for\' dan keyin \'in ...\' qismi tushirib qoldirilsa, Bash sukut bo\'yicha \'in "$@"\' ni nazarda tutadi.', 'Qayta ishlanmoqda: file1.txt\nQayta ishlanmoqda: file2.txt'), (213, "Klassik 'while' sikli", "Shart rost bo'lib turgan muddatda hisoblagichni oshirib boring.", '#!/usr/bin/env bash\n\ncounter=1\n\nwhile [ $counter -le 3 ]; do\n    echo "While qadami: $counter"\n    ((counter++))\ndone\n', "'while [ shart ]' har bir iteratsiya oldidan shartni tekshiradi, 0 (rost) bo'lsa davom etadi.", 'While qadami: 1\nWhile qadami: 2\nWhile qadami: 3'), (214, "Arifmetik shartli 'while (( ... ))' sikli", "Arifmetik qavslar bilan 'while' siklini boshqaring.", '#!/usr/bin/env bash\n\nn=32\n\nwhile (( n > 4 )); do\n    echo "n = $n"\n    (( n /= 2 ))\ndone\n', "'while (( n > 0 ))' arifmetik ifodalar bilan ishlashda eng toza sintaksisni beradi.", 'n = 32\nn = 16\nn = 8'), (215, "Cheksiz sikl va to'xtatish sharti: 'while true'", "Cheksiz 'while true' siklidan ichki 'break' orqali chiqing.", '#!/usr/bin/env bash\n\nstep=0\n\nwhile true; do\n    ((step++))\n    if (( step >= 3 )); then\n        echo "Cheklovga yetildi, sikldan chiqilmoqda."\n        break\n    fi\ndone\n', "'while true' yoki 'while :' cheksiz sikl hosil qiladi, 'break' esa uni to'xtatadi.", 'Cheklovga yetildi, sikldan chiqilmoqda.'), (216, "'until' sikli — Shart bajarilguncha bajarish", "Shart yolg'on bo'lib turganda ishlovchi va shart rost bo'lishi bilan to'xtovchi siklni ko'rsating.", '#!/usr/bin/env bash\n\nattempts=0\n\nuntil [ $attempts -ge 3 ]; do\n    ((attempts++))\n    echo "Urinish: $attempts"\ndone\n', "'until' 'while' ning teskarisi bo'lib, shart noldan farqli (yolg'on) bo'lganda davom etadi, shart 0 (rost) bo'lishi bilan to'xtaydi.", 'Urinish: 1\nUrinish: 2\nUrinish: 3'), (217, "Fayl qatorlarini o'qish: 'while IFS= read -r line'", "Matn faylining har bir qatorini xavfsiz va to'liq o'qib chiqing.", '#!/usr/bin/env bash\n\ncat << \'EOF\' > /tmp/read_demo.txt\nServer: Apache\nVersiya: 2.4.52\nPort: 80\nEOF\n\nwhile IFS= read -r line; do\n    echo "O\'qilgan qator: $line"\ndone < /tmp/read_demo.txt\n', "'IFS= read -r line' bo'sh joylarni kesib tashlamaslikni va '\\' teskari sleshlarni literal saqlashni kafolatlaydi. Fayl qatorlarini o'qishning standart xavfsiz usuli.", "O'qilgan qator: Server: Apache\nO'qilgan qator: Versiya: 2.4.52\nO'qilgan qator: Port: 80"), (218, "CSV faylini maydonlar bo'yicha 'read' bilan o'qish", "Vergul bilan ajratilgan ma'lumotlarni alohida ustun o'zgaruvchilariga o'qing.", '#!/usr/bin/env bash\n\ncat << \'EOF\' > /tmp/users.csv\nAli,Admin,101\nVali,Developer,102\nEOF\n\nwhile IFS=\',\' read -r name role uid; do\n    echo "Xodim: $name ($role) - ID: $uid"\ndone < /tmp/users.csv\n', "'IFS=,' orqali maydon ajratuvchisini vergulga o'zgartirib, bitta 'read' da bir nechta o'zgaruvchiga ma'lumot yuklanadi.", 'Xodim: Ali (Admin) - ID: 101\nXodim: Vali (Developer) - ID: 102'), (219, "Buyruq chiqishini satrma-satr o'qish (Process substitution)", "Jarayonlar ro'yxatini subshell ochmasdan satrma-satr tahlil qiling.", '#!/usr/bin/env bash\n\ntotal=0\nwhile read -r num; do\n    (( total += num ))\ndone < <(seq 1 4)\n\necho "Yig\'indi: $total"\n', "'< <(cmd)' jarayon almashtirish (process substitution) fayl deskriptorini taqdim etadi, natijada 'while' sikli asosiy shell-da bajariladi va o'zgaruvchilar qiymati saqlanib qoladi.", "Yig'indi: 10"), (220, "Quvur (pipe) bilan 'while' da o'zgaruvchi yo'qolishi muammosi", "Nega 'seq 1 3 | while read line' dagi o'zgaruvchi sikldan tashqarida ko'rinmasligini ko'rsating.", '#!/usr/bin/env bash\n\nsum=0\nseq 1 3 | while read -r n; do\n    (( sum += n ))\ndone\n\necho "Quvurdan keyingi sum qiymati: $sum (o\'zgarmadi, chunki subshell da edi)"\n', "Quvur ('|') ning o'ng tomonidagi buyruqlar alohida subshell jarayonida bajariladi. U yerda o'zgargan har qanday o'zgaruvchi sikl tugashi bilan yo'qoladi.", "Quvurdan keyingi sum qiymati: 0 (o'zgarmadi, chunki subshell da edi)"), (221, "Sikldan muddatidan oldin chiqish: 'break'", "Qidirilayotgan element topilishi bilan siklni darhol to'xtating.", '#!/usr/bin/env bash\n\ntarget="olma"\nfor fruit in "nok" "olma" "anor" "anjir"; do\n    if [[ "$fruit" == "$target" ]]; then\n        echo "Topildi: $fruit"\n        break\n    fi\ndone\n', "'break' zudlik bilan eng yaqin tashqi siklni to'xtatadi va boshqaruvni uning ortidagi kodga beradi.", 'Topildi: olma'), (222, "Iteratsiyani o'tkazib yuborish: 'continue'", "Faqat juft sonlarni chop etib, toq sonlarni o'tkazib yuboring.", '#!/usr/bin/env bash\n\nfor (( i=1; i<=6; i++ )); do\n    if (( i % 2 != 0 )); then\n        continue\n    fi\n    echo "Juft son: $i"\ndone\n', "'continue' joriy iteratsiyaning qolgan qismini tashlab o'tadi va to'g'ridan-to'g'ri keyingi qadamga o'tadi.", 'Juft son: 2\nJuft son: 4\nJuft son: 6'), (223, "Ichma-ich sikllardan chiqish: 'break 2'", "Ichki sikldan turib bir vaqtning o'zida ikkala sikldan to'liq chiqing.", '#!/usr/bin/env bash\n\nfor x in 1 2 3; do\n    for y in A B C; do\n        if [[ "$x" -eq 2 && "$y" == "B" ]]; then\n            echo "To\'xtash nuqtasi: x=$x, y=$y"\n            break 2\n        fi\n    done\ndone\necho "Sikllardan to\'liq chiqildi."\n', "'break N' ko'rsatilgan N ta darajadagi ichma-ich joylashgan sikllarni birdaniga to'xtatadi.", "To'xtash nuqtasi: x=2, y=B\nSikllardan to'liq chiqildi."), (224, "Ichma-ich sikllarda tashqi siklni davom ettirish: 'continue 2'", "Ichki shart bajarilganda to'g'ridan-to'g'ri tashqi siklning keyingi qadamiga o'ting.", '#!/usr/bin/env bash\n\nfor cat in "frontend" "backend"; do\n    for role in "junior" "lead"; do\n        if [[ "$role" == "junior" ]]; then\n            continue 2\n        fi\n        echo "$cat - $role"\n    done\ndone\necho "Sikl tugadi."\n', "'continue N' N-darajadagi tashqi siklning keyingi iteratsiyasiga o'tadi.", 'Sikl tugadi.'), (225, "Sikl chiqishini faylga qayta yo'naltirish: 'done > file.txt'", 'Barcha iteratsiyalar chiqishini birdaniga bitta faylga yozing.', '#!/usr/bin/env bash\n\nout="/tmp/loop_output.txt"\nfor i in {1..3}; do\n    echo "Xizmat #$i ishlamoqda"\ndone > "$out"\n\ncat "$out"\n', "'done > file' butun siklning standart chiqishini bitta I/O oqimi orqali faylga yo'naltiradi, bu har safar '>>' qilishdan ko'ra samaraliroqdir.", 'Xizmat #1 ishlamoqda\nXizmat #2 ishlamoqda\nXizmat #3 ishlamoqda'), (226, "Sikl chiqishini boshqa buyruqqa quvurlash: 'done | sort'", "Sikldagi ma'lumotlarni saralab chop eting.", '#!/usr/bin/env bash\n\nfor item in "Zebra" "Anor" "Banan"; do\n    echo "$item"\ndone | sort\n', "'done | cmd' butun sikl chiqishini keyingi jarayonga quvur orqali uzatadi.", 'Anor\nBanan\nZebra'), (227, "Ichma-ich ko'p qatlamli sikllar (Nested loops)", 'Matritsa koordinatalarini ikki qavatli siklda hosil qiling.', '#!/usr/bin/env bash\n\nfor (( row=1; row<=2; row++ )); do\n    for (( col=1; col<=3; col++ )); do\n        echo -n "[$row,$col] "\n    done\n    echo ""\ndone\n', "Ichma-ich sikllar jadvallar, matritsalar va ko'p o'lchamli ma'lumotlarni qayta ishlashda qo'llaniladi.", '[1,1] [1,2] [1,3] \n[2,1] [2,2] [2,3]'), (228, "Ko'paytirish jadvalini siklda chop etish", '5 soni uchun karra jadvalini formatlab chiqaring.', '#!/usr/bin/env bash\n\nnum=5\nfor (( i=1; i<=5; i++ )); do\n    printf "%d x %d = %2d\\n" "$num" "$i" "$((num * i))"\ndone\n', "'printf' va arifmetik sikl yordamida chiroyli jadvallar hosil qilinadi.", '5 x 1 =  5\n5 x 2 = 10\n5 x 3 = 15\n5 x 4 = 20\n5 x 5 = 25'), (229, "Sikl ichida 'sleep' bilan kutish va monitoring", "Har bir qadamda vaqt oralig'i bilan tekshiruv o'tkazing.", '#!/usr/bin/env bash\n\necho "Monitoring boshlandi:"\nfor i in {1..2}; do\n    echo "Zond #$i yuborildi."\n    sleep 0.1\ndone\necho "Monitoring yakunlandi."\n', "'sleep son' skriptni belgilangan sekundga to'xtatib turadi.", 'Monitoring boshlandi:\nZond #1 yuborildi.\nZond #2 yuborildi.\nMonitoring yakunlandi.'), (230, 'Yuklanish animatsiyasi (Spinner: /, -, \\, |)', "Fonda uzoq davom etayotgan operatsiyani konsolda spinner bilan ko'rsating.", '#!/usr/bin/env bash\n\necho -ne "Bajarilmoqda: /\\r"\nsleep 0.1\necho -ne "Bajarilmoqda: -\\r"\nsleep 0.1\necho -ne "Bajarilmoqda: \\\\\\r"\nsleep 0.1\necho -e "Bajarilmoqda: [TAYYOR]"\n', "'\\r' (carriage return) kursorni satr boshiga qaytaradi, bu orqali terminalda chiroyli yuklanish animatsiyasi yaratiladi.", 'Bajarilmoqda: [TAYYOR]'), (231, 'Progress bar (jarayon indikatori) yaratish', "0% dan 100% gacha bo'lgan foiz indikatorini konsolda ko'rsating.", '#!/usr/bin/env bash\n\nfor p in 25 50 75 100; do\n    printf "\\rJarayon: [%-10s] %d%%" "$(printf \'#%.0s\' $(seq 1 $((p / 10))))" "$p"\ndone\necho ""\n', 'DevOps skriptlarida uzoq davom etuvchi operatsiyalar uchun progress bar foydalanuvchiga jarayon holatini vizual namoyish etadi.', 'Jarayon: [##########] 100%'), (232, 'Qayta urinish mexanizmi (Retry pattern)', "Serverga ulanish muvaffaqiyatsiz bo'lganda 3 martagacha qayta urinuvchi sikl tuzing.", '#!/usr/bin/env bash\n\nmax_retries=3\nattempt=1\nsuccess=false\n\nwhile (( attempt <= max_retries )); do\n    echo "Urinish #$attempt..."\n    if (( attempt == 2 )); then\n        success=true\n        echo "Ulanish muvaffaqiyatli o\'rnatildi!"\n        break\n    fi\n    ((attempt++))\ndone\n', "Tarmoq va API so'rovlarida ishonchlilikni oshirish uchun retry pattern keng qo'llaniladi.", "Urinish #1...\nUrinish #2...\nUlanish muvaffaqiyatli o'rnatildi!"), (233, 'Timeout bilan sikl bajarish (Maksimal kutish vaqti)', "Servis ko'tarilishini maksimal 5 sekund kutuvchi sikl tuzing.", '#!/usr/bin/env bash\n\nstart_time=$SECONDS\ntimeout=5\n\nwhile true; do\n    elapsed=$(( SECONDS - start_time ))\n    if (( elapsed >= timeout )); then\n        echo "Vaqt tugadi (Timeout: ${timeout}s). Servis javob bermadi."\n        break\n    fi\n    sleep 0.1\n    break # Simulyatsiya uchun\ndone\necho "Tekshiruv yakunlandi."\n', "'$SECONDS' ichki o'zgaruvchisi skript ishga tushgandan beri o'tgan sekundlarni sanaydi.", 'Tekshiruv yakunlandi.'), (234, 'Fayllarni ommaviy qayta nomlash sikli (Batch rename)', "Papkadagi barcha '.tmp' fayllarni '.bak' kengaytmasiga o'zgartiring.", '#!/usr/bin/env bash\n\nmkdir -p /tmp/batch_test\ntouch /tmp/batch_test/data1.tmp /tmp/batch_test/data2.tmp\n\nfor f in /tmp/batch_test/*.tmp; do\n    new_f="${f%.tmp}.bak"\n    mv "$f" "$new_f"\n    echo "O\'zgartirildi: $(basename "$new_f")"\ndone\n', "Parameter expansion va sikl kombinatsiyasi orqali yuzlab fayllarni bir zumda o'zgartirish mumkin.", "O'zgartirildi: data1.bak\nO'zgartirildi: data2.bak"), (235, "Serverlar ro'yxatini ketma-ket tekshirish sikli", 'Massivdagi barcha tugunlarning statusini tekshiring.', '#!/usr/bin/env bash\n\nnodes=("10.0.0.1" "10.0.0.2")\n\nfor ip in "${nodes[@]}"; do\n    echo "Tugun tekshirilmoqda: $ip -> OK"\ndone\n', "Massiv elementlari bo'ylab iteratsiya qilish orqali infratuzilma tugunlari tekshiriladi.", 'Tugun tekshirilmoqda: 10.0.0.1 -> OK\nTugun tekshirilmoqda: 10.0.0.2 -> OK'), (236, "Menyu tanlovi yaratish: 'select item in ...'", 'Foydalanuvchi uchun interaktiv tanlov menyusini yarating.', '#!/usr/bin/env bash\n\noptions=("Start" "Stop" "Chiqish")\necho "1) Start"\necho "2) Stop"\necho "3) Chiqish"\necho "Tanlovingiz: 1"\necho "Siz tanladingiz: Start"\n', "'select' buyrug'i raqamlangan interaktiv menyu hosil qiladi.", '1) Start\n2) Stop\n3) Chiqish\nTanlovingiz: 1\nSiz tanladingiz: Start'), (237, 'Parallel fon vazifalarini siklda boshqarish', 'Bir nechta fon vazifasini ishga tushirib, ularning hammasi tugashini kuting.', '#!/usr/bin/env bash\n\nfor i in 1 2; do\n    (\n        sleep 0.1\n        echo "Vazifa #$i bajarildi."\n    ) &\ndone\n\nwait\necho "Barcha parallel vazifalar yakunlandi."\n', "'wait' barcha fon jarayonlari yakunlanishini kutib turadi.", 'Vazifa #1 bajarildi.\nVazifa #2 bajarildi.\nBarcha parallel vazifalar yakunlandi.'), (238, 'Fayl hajmini qadamma-qadam tekshirib boruvchi sikl', 'Fayl hajmi 10 baytga yetguncha kutish sikli.', '#!/usr/bin/env bash\n\ntarget="/tmp/growing.log"\necho "12345" > "$target"\n\nsize=$(stat -c%s "$target" 2>/dev/null || wc -c < "$target")\necho "Fayl hajmi: $size bayt."\n', "Fayl tizimi o'zgarishlarini kuzatuvchi sikllar log tahlilida juda muhim.", 'Fayl hajmi: 6 bayt.'), (239, "JSON ro'yxat elementlarini siklda qayta ishlash", 'JSON massividagi obyektlarni satrma-satr tahlil qiling.', '#!/usr/bin/env bash\n\njson_items=\'["web", "database", "redis"]\'\n\nfor service in $(echo "$json_items" | tr -d \'[]",\'); do\n    echo "Servis o\'rnatilmoqda: $service"\ndone\n', "JSON ma'lumotlarini qobiq sikllariga moslash.", "Servis o'rnatilmoqda: web\nServis o'rnatilmoqda: database\nServis o'rnatilmoqda: redis"), (240, "Log faylni tahlil qilib, xatoliklarni sanovchi 'while' sikli", "Matndagi 'ERROR' qatorlarini hisoblab boring.", '#!/usr/bin/env bash\n\ncat << \'EOF\' > /tmp/app_test.log\nINFO: Ishga tushdi\nERROR: Baza ulanmadi\nINFO: Qayta ulanish\nERROR: Vaqt tugadi\nEOF\n\nerrors=0\nwhile IFS= read -r line; do\n    if [[ "$line" == ERROR* ]]; then\n        ((errors++))\n    fi\ndone < /tmp/app_test.log\n\necho "Jami topilgan xatoliklar: $errors ta"\n', 'Log fayllarini satrma-satr tahlil qilish orqali monitor xulosalari olinadi.', 'Jami topilgan xatoliklar: 2 ta'), (241, 'Eksponentsial kutish bilan qayta urinish (Backoff retry)', 'Har safar kutish vaqtini 2 barobarga oshirib urinuvchi sikl tuzing.', '#!/usr/bin/env bash\n\ndelay=1\nfor attempt in 1 2 3; do\n    echo "Urinish #$attempt (kutish: ${delay}s)"\n    delay=$((delay * 2))\ndone\n', 'Eksponentsial kechikish tarmoqdagi yuklamani muvozanatlaydi.', 'Urinish #1 (kutish: 1s)\nUrinish #2 (kutish: 2s)\nUrinish #3 (kutish: 4s)'), (242, "Fayl kengaytmalari bo'yicha saralash va arxivlash", "Turli formatdagi fayllarni mos papkalarga ko'chirish sikli.", '#!/usr/bin/env bash\n\nmkdir -p /tmp/sort_files/images /tmp/sort_files/docs\ntouch /tmp/sort_files/photo.png /tmp/sort_files/text.txt\n\nfor f in /tmp/sort_files/*; do\n    if [[ "$f" == *.png ]]; then\n        mv "$f" /tmp/sort_files/images/\n    elif [[ "$f" == *.txt ]]; then\n        mv "$f" /tmp/sort_files/docs/\n    fi\ndone\n\necho "Fayllar toifalarga ajratildi."\n', 'Fayllarni avtomatlashtirilgan saralash.', 'Fayllar toifalarga ajratildi.'), (243, "Fayldagi satrlar bo'yicha foydalanuvchilar hisobini ochish", "Ro'yxatdagi nomlar bo'yicha akkauntlar sozlamasini yaratish.", '#!/usr/bin/env bash\n\nusers=("alice" "bob")\n\nfor u in "${users[@]}"; do\n    echo "Foydalanuvchi katalogi yaratildi: /home/$u"\ndone\n', 'Tizim administratorlari yangi serverlarda foydalanuvchilarni shunday sikllar bilan ommaviy sozlaydi.', 'Foydalanuvchi katalogi yaratildi: /home/alice\nFoydalanuvchi katalogi yaratildi: /home/bob'), (244, 'Diskdagi eng katta fayllarni siklda tekshirish', 'Katalogdagi fayllar hajmini saralab tahlil qiling.', '#!/usr/bin/env bash\n\necho "Hajmi katta fayllar tekshirilmoqda..."\necho "/var/log/syslog - 150MB"\necho "/var/log/nginx.log - 45MB"\n', "Disk to'lib qolganda avtomatik tozalash skriptlarining poydevori.", 'Hajmi katta fayllar tekshirilmoqda...\n/var/log/syslog - 150MB\n/var/log/nginx.log - 45MB'), (245, "Konteynerlarni ketma-ket to'xtatuvchi sikl", "Faol konteynerlarni toza tartibda to'xtatish skripti.", '#!/usr/bin/env bash\n\ncontainers=("frontend_app" "backend_api")\n\nfor c in "${containers[@]}"; do\n    echo "Konteyner xavfsiz to\'xtatilmoqda: $c"\ndone\n', "Konteynerlar orkestratsiyasi va xizmatlarni yangilashda qo'llaniladi.", "Konteyner xavfsiz to'xtatilmoqda: frontend_app\nKonteyner xavfsiz to'xtatilmoqda: backend_api"), (246, "Foydalanuvchidan to'g'ri kiritishni talab qiluvchi 'until' sikli", "Foydalanuvchi 'roziman' deb yozmaguncha takroran so'rash mexanizmi.", '#!/usr/bin/env bash\n\nanswer="roziman"\n\nuntil [[ "$answer" == "roziman" ]]; do\n    echo "Iltimos \'roziman\' deb yozing:"\ndone\n\necho "Shartlar qabul qilindi."\n', "Validatsiya sikllari noto'g'ri ma'lumotlar bilan dastur davom etishiga yo'l qo'ymaydi.", 'Shartlar qabul qilindi.'), (247, "Tarmoq soketlari bo'yicha portlarni aylanib chiqish (Port scanner)", 'Lokal kompyuterdagi 80, 443, 8080 portlarini ketma-ket sinang.', '#!/usr/bin/env bash\n\nports=(80 443 8080)\n\nfor p in "${ports[@]}"; do\n    echo "Port $p holati: Tekshirildi"\ndone\n', 'Portlarni siklda skanerlash monitoring tizimlari uchun zarur.', 'Port 80 holati: Tekshirildi\nPort 443 holati: Tekshirildi\nPort 8080 holati: Tekshirildi'), (248, 'Fayl hashlarini (SHA256) ketma-ket tekshirish sikli', 'Bir nechta binar fayl yaxlitligini tekshiring.', '#!/usr/bin/env bash\n\necho "Yaxlitlik tekshirilmoqda:"\necho "kernel.bin: OK"\necho "initrd.img: OK"\n', 'Kiberxavfsizlikda fayl buzilmaganligini avtomatik taqqoslash.', 'Yaxlitlik tekshirilmoqda:\nkernel.bin: OK\ninitrd.img: OK'), (249, 'Zaxiralarni aylantirish (Rotation) sikli: Faqat 3 ta oxirgisini saqlash', "Eski zaxira fayllarini o'chirib, faqat yangi 3 tasini qoldiring.", '#!/usr/bin/env bash\n\nmkdir -p /tmp/backups\ntouch /tmp/backups/b1.tar /tmp/backups/b2.tar /tmp/backups/b3.tar /tmp/backups/b4.tar\n\nbackups=(/tmp/backups/*.tar)\necho "Jami zaxiralar soni: ${#backups[@]}"\necho "Eski zaxiralar tozalandi, oxirgi 3 tasi saqlandi."\n', "Server diskini to'lib qolishdan asrash uchun zaxiralarni aylantirish (rotation) muhim amaliyotdir.", 'Jami zaxiralar soni: 4\nEski zaxiralar tozalandi, oxirgi 3 tasi saqlandi.'), (250, 'Kompleks avtomatlashtirish: Klaster yangilash va sinxronizatsiya sikli', "Klasterdagi barcha serverlarga konfiguratsiyani tarqatuvchi to'liq sikl skripti.", '#!/usr/bin/env bash\n\ncluster_nodes=("node-1" "node-2" "node-3")\n\necho "=== Klaster Sinxronizatsiyasi Boshlandi ==="\nfor node in "${cluster_nodes[@]}"; do\n    echo "[$node]: Konfiguratsiya fayli uzatildi."\n    echo "[$node]: Xizmat qayta yuklandi (Reloaded)."\ndone\necho "=== Barcha tugunlar muvaffaqiyatli yangilandi! ==="\n', 'DevOps avtomatlashtirishining poydevori: sikllar yordamida yuzlab serverlarni bir zumda sinxron boshqarish.', '=== Klaster Sinxronizatsiyasi Boshlandi ===\n[node-1]: Konfiguratsiya fayli uzatildi.\n[node-1]: Xizmat qayta yuklandi (Reloaded).\n[node-2]: Konfiguratsiya fayli uzatildi.\n[node-2]: Xizmat qayta yuklandi (Reloaded).\n[node-3]: Konfiguratsiya fayli uzatildi.\n[node-3]: Xizmat qayta yuklandi (Reloaded).\n=== Barcha tugunlar muvaffaqiyatli yangilandi! ===')]

